import{at as e,it as t,n,vt as r}from"./chunks/framework.a_MF1dSK.js";var i=JSON.parse(`{"title":"Protocolo Clínico CARDIO Fortaleza","description":"","frontmatter":{},"headers":[],"relativePath":"protocolos/Protocolo_Clinico.md","filePath":"protocolos/Protocolo_Clinico.md"}`),a={name:`protocolos/Protocolo_Clinico.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="protocolo-clinico-cardio-fortaleza" tabindex="-1">Protocolo Clínico CARDIO Fortaleza <a class="header-anchor" href="#protocolo-clinico-cardio-fortaleza" aria-label="Permalink to “Protocolo Clínico CARDIO Fortaleza”">​</a></h1><h2 id="introducao-e-atuacao-da-equipe" tabindex="-1">Introdução e Atuação da Equipe <a class="header-anchor" href="#introducao-e-atuacao-da-equipe" aria-label="Permalink to “Introdução e Atuação da Equipe”">​</a></h2><p>Os protocolos clínicos são guias práticos baseados em evidências para o rastreamento, diagnóstico, tratamento e controle de HA e DM na APS.</p><h3 id="atuacao-multiprofissional" tabindex="-1">Atuação Multiprofissional <a class="header-anchor" href="#atuacao-multiprofissional" aria-label="Permalink to “Atuação Multiprofissional”">​</a></h3><p>Integração de médicos, enfermeiros, agentes, nutricionistas, etc.</p><ul><li><strong>Estratégias</strong>: Educação do paciente, Apoio social, Letramento e motivação, Automonitoramento, Facilitação do acesso.</li><li>O foco é um cuidado intersetorial e centrado nas necessidades do usuário.</li></ul><h2 id="hipertensao-arterial-protocolo-pratico" tabindex="-1">Hipertensão Arterial: Protocolo Prático <a class="header-anchor" href="#hipertensao-arterial-protocolo-pratico" aria-label="Permalink to “Hipertensão Arterial: Protocolo Prático”">​</a></h2><h3 id="rastreamento-e-diagnostico" tabindex="-1">Rastreamento e Diagnóstico <a class="header-anchor" href="#rastreamento-e-diagnostico" aria-label="Permalink to “Rastreamento e Diagnóstico”">​</a></h3><p>Adultos ≥ 18 anos devem aferir a PA anualmente. Diagnóstico confirmado com PA ≥ 140/90 mmHg em 2 ocasiões. Diferença &gt;15mmHg entre os braços indica risco aumentado.</p><h3 id="classificacao-da-pa" tabindex="-1">Classificação da PA <a class="header-anchor" href="#classificacao-da-pa" aria-label="Permalink to “Classificação da PA”">​</a></h3><table tabindex="0"><thead><tr><th>Classificação</th><th>PAS (mmHg)</th><th></th><th>PAD (mmHg)</th></tr></thead><tbody><tr><td>Normal</td><td>&lt; 120</td><td>e</td><td>&lt; 80</td></tr><tr><td>Pré-hipertensão</td><td>120-139</td><td>e/ou</td><td>80-89</td></tr><tr><td>Estágio 1</td><td>140-159</td><td>e/ou</td><td>90-99</td></tr><tr><td>Estágio 2</td><td>160-179</td><td>e/ou</td><td>100-109</td></tr><tr><td>Estágio 3</td><td>≥ 180</td><td>e/ou</td><td>≥ 110</td></tr></tbody></table><h3 id="estratificacao-de-risco-cv-e-exames" tabindex="-1">Estratificação de Risco CV e Exames <a class="header-anchor" href="#estratificacao-de-risco-cv-e-exames" aria-label="Permalink to “Estratificação de Risco CV e Exames”">​</a></h3><p>Avaliar lesões de órgãos-alvo (LOA) via ECG, Taxa de Filtração Glomerular (DRC) e Albuminúria. Fatores agravantes: Diabetes, tabagismo, dislipidemia, obesidade.</p><h2 id="ha-tratamento-e-metas" tabindex="-1">HA: Tratamento e Metas <a class="header-anchor" href="#ha-tratamento-e-metas" aria-label="Permalink to “HA: Tratamento e Metas”">​</a></h2><h3 id="tratamento-nao-medicamentoso" tabindex="-1">Tratamento Não Medicamentoso <a class="header-anchor" href="#tratamento-nao-medicamentoso" aria-label="Permalink to “Tratamento Não Medicamentoso”">​</a></h3><p>Dieta DASH, redução de sódio (&lt;2g/dia), atividade física (150 min/sem), redução de álcool e cessação do tabagismo.</p><h3 id="tratamento-medicamentoso-octogono-da-ha" tabindex="-1">Tratamento Medicamentoso (Octógono da HA) <a class="header-anchor" href="#tratamento-medicamentoso-octogono-da-ha" aria-label="Permalink to “Tratamento Medicamentoso (Octógono da HA)”">​</a></h3><ul><li>1ª Linha: Diuréticos Tiazídicos (TIAZ), Inibidores da ECA (IECA) ou BRA, Bloqueadores de Cálcio (BCC).</li><li>Metas: Monoterapia inicial para risco baixo. Associação de 2 medicamentos para estágios 1 (alto risco), 2 e 3.</li><li>Meta de PA: &lt; 130/80 mmHg para a maioria dos pacientes.</li></ul><h2 id="ha-grupos-especificos" tabindex="-1">HA: Grupos Específicos <a class="header-anchor" href="#ha-grupos-especificos" aria-label="Permalink to “HA: Grupos Específicos”">​</a></h2><h3 id="criancas-adolescentes" tabindex="-1">Crianças/Adolescentes <a class="header-anchor" href="#criancas-adolescentes" aria-label="Permalink to “Crianças/Adolescentes”">​</a></h3><p>Baseado em percentil de estatura. HA se percentil ≥ 95. Recomendado aferição anual a partir de 3 anos.</p><h3 id="gestantes" tabindex="-1">Gestantes <a class="header-anchor" href="#gestantes" aria-label="Permalink to “Gestantes”">​</a></h3><p>HA se ≥ 140/90 mmHg. Tratamento imediato se ≥ 150-160/100-110. Medicamentos permitidos: Metildopa, Nifedipina. <strong>Contraindicados:</strong> IECA, BRA. Risco de Pré-eclâmpsia.</p><h3 id="idosos" tabindex="-1">Idosos <a class="header-anchor" href="#idosos" aria-label="Permalink to “Idosos”">​</a></h3><p>Diagnóstico cuidadoso (pseudohipertensão). Meta padrão &lt; 130/80, mas ajustada se fragilidade. Evitar polifarmácia.</p><h3 id="mulheres" tabindex="-1">Mulheres <a class="header-anchor" href="#mulheres" aria-label="Permalink to “Mulheres”">​</a></h3><p>Atenção a anticoncepcionais orais, menopausa e histórico de complicações gestacionais.</p><h2 id="ha-urgencia-e-encaminhamento" tabindex="-1">HA: Urgência e Encaminhamento <a class="header-anchor" href="#ha-urgencia-e-encaminhamento" aria-label="Permalink to “HA: Urgência e Encaminhamento”">​</a></h2><h3 id="crises-hipertensivas" tabindex="-1">Crises Hipertensivas <a class="header-anchor" href="#crises-hipertensivas" aria-label="Permalink to “Crises Hipertensivas”">​</a></h3><p>PA ≥ 180/110 mmHg.</p><ul><li><strong>Urgência</strong>: Sem LOA aguda. Redução gradual com medicações orais (reavaliação 1-7 dias).</li><li><strong>Emergência</strong>: Com LOA aguda (AVC, dissecção aórtica, infarto, Eclâmpsia). Risco iminente de morte. Necessita de redução rápida endovenosa e internação em UTI.</li></ul><h3 id="criterios-de-encaminhamento" tabindex="-1">Critérios de Encaminhamento <a class="header-anchor" href="#criterios-de-encaminhamento" aria-label="Permalink to “Critérios de Encaminhamento”">​</a></h3><ul><li>Nefrologista/Endocrinologista: HA secundária, Nefropatia grave.</li><li>Cardiologista: HA resistente (uso de 3 medicamentos), HVE, Angina.</li><li>Neurologista: AVC sem investigação prévia.</li></ul><h2 id="diabetes-mellitus-protocolo-pratico" tabindex="-1">Diabetes Mellitus: Protocolo Prático <a class="header-anchor" href="#diabetes-mellitus-protocolo-pratico" aria-label="Permalink to “Diabetes Mellitus: Protocolo Prático”">​</a></h2><h3 id="rastreamento-dm2" tabindex="-1">Rastreamento (DM2) <a class="header-anchor" href="#rastreamento-dm2" aria-label="Permalink to “Rastreamento (DM2)”">​</a></h3><p>Adultos ≥ 35 anos (universal) ou &lt; 35 com sobrepeso + 1 fator de risco.</p><h3 id="diagnostico" tabindex="-1">Diagnóstico <a class="header-anchor" href="#diagnostico" aria-label="Permalink to “Diagnóstico”">​</a></h3><table tabindex="0"><thead><tr><th>Exame</th><th>Pré-diabetes</th><th>DM</th></tr></thead><tbody><tr><td>Glicemia de Jejum</td><td>100-125</td><td>≥ 126</td></tr><tr><td>TTGO (2 horas)</td><td>140-199</td><td>≥ 200</td></tr><tr><td>HbA1c (%)</td><td>5,7 - 6,4</td><td>≥ 6,5</td></tr></tbody></table><h3 id="tratamento-dm2" tabindex="-1">Tratamento DM2 <a class="header-anchor" href="#tratamento-dm2" aria-label="Permalink to “Tratamento DM2”">​</a></h3><ul><li>Metformina (Monoterapia inicial).</li><li>Terapia combinada se HbA1c estiver fora da meta.</li><li>Para alto risco CV, associar iSGLT2 ou GLP1.</li><li>Insulina se hiperglicemia acentuada (HbA1c ≥ 9%) ou sintomas.</li></ul><h3 id="metas-glicemicas" tabindex="-1">Metas Glicêmicas <a class="header-anchor" href="#metas-glicemicas" aria-label="Permalink to “Metas Glicêmicas”">​</a></h3><p>Jejum: 80-130 mg/dL. Pós-prandial: &lt; 180 mg/dL.</p><h2 id="dm-prevencao-de-pe-diabetico" tabindex="-1">DM: Prevenção de Pé Diabético <a class="header-anchor" href="#dm-prevencao-de-pe-diabetico" aria-label="Permalink to “DM: Prevenção de Pé Diabético”">​</a></h2><h3 id="fatores-de-risco" tabindex="-1">Fatores de Risco <a class="header-anchor" href="#fatores-de-risco" aria-label="Permalink to “Fatores de Risco”">​</a></h3><p>Perda de sensibilidade, doença arterial periférica, deformidades e úlceras prévias.</p><h3 id="exame-anual-dos-pes" tabindex="-1">Exame Anual dos Pés <a class="header-anchor" href="#exame-anual-dos-pes" aria-label="Permalink to “Exame Anual dos Pés”">​</a></h3><ul><li>Teste com monofilamento de 10g (Semmes-Weinstein) ou Ipswich Touch Test (IpTT).</li><li>Palpação de pulsos.</li></ul><h3 id="autocuidado" tabindex="-1">Autocuidado <a class="header-anchor" href="#autocuidado" aria-label="Permalink to “Autocuidado”">​</a></h3><p>Inspeção diária, hidratação (evitar entre os dedos), corte reto de unhas, uso de calçados adequados e não usar agentes químicos para calos.</p><h2 id="dm-grupos-especificos" tabindex="-1">DM: Grupos Específicos <a class="header-anchor" href="#dm-grupos-especificos" aria-label="Permalink to “DM: Grupos Específicos”">​</a></h2><h3 id="criancas-adolescentes-1" tabindex="-1">Crianças/Adolescentes <a class="header-anchor" href="#criancas-adolescentes-1" aria-label="Permalink to “Crianças/Adolescentes”">​</a></h3><p>Rastreamento de DM2 aos 10 anos se sobrepeso + risco. Para DM1, uso intensivo de insulina basal-bolus (SICI preferencial se &lt; 7 anos).</p><h3 id="gestantes-1" tabindex="-1">Gestantes <a class="header-anchor" href="#gestantes-1" aria-label="Permalink to “Gestantes”">​</a></h3><p>Rastreamento TOTG 24-28 semanas. Diagnóstico DMG se Jejum ≥ 92, 1h ≥ 180, 2h ≥ 153. Tratamento: Dieta inicialmente. Metformina/Insulina se necessário (Glibenclamida é contraindicada).</p><h3 id="idosos-1" tabindex="-1">Idosos <a class="header-anchor" href="#idosos-1" aria-label="Permalink to “Idosos”">​</a></h3><p>Avaliar fragilidade. Risco alto de hipoglicemia severa. Permitida a &quot;desintensificação&quot; do tratamento e flexibilização de metas (HbA1c &lt; 8% ou 8.5% dependendo da fragilidade) para evitar riscos associados à polifarmácia e sarcopenia.</p><h2 id="dm1-diagnostico-e-tratamento" tabindex="-1">DM1: Diagnóstico e Tratamento <a class="header-anchor" href="#dm1-diagnostico-e-tratamento" aria-label="Permalink to “DM1: Diagnóstico e Tratamento”">​</a></h2><h3 id="diagnostico-dm1" tabindex="-1">Diagnóstico DM1 <a class="header-anchor" href="#diagnostico-dm1" aria-label="Permalink to “Diagnóstico DM1”">​</a></h3><p>Sintomas clássicos (poliúria, polidipsia, perda de peso) + Glicemia Aleatória ≥ 200, ou Jejum ≥ 126, ou HbA1c ≥ 6,5%. Pode abrir quadro com cetoacidose.</p><h3 id="tratamento" tabindex="-1">Tratamento <a class="header-anchor" href="#tratamento" aria-label="Permalink to “Tratamento”">​</a></h3><p>Insulinoterapia intensiva (Basal-Bolus) em todos os casos. Uso de Insulina NPH/Regular, ou Análogos de Ação Prolongada/Rápida conforme critérios do PCDT.</p><h3 id="metas-adultos" tabindex="-1">Metas (Adultos) <a class="header-anchor" href="#metas-adultos" aria-label="Permalink to “Metas (Adultos)”">​</a></h3><p>Jejum 70-130, Pós-prandial &lt; 180, HbA1c &lt; 7.0%. Monitoramento contínuo (AMGC).</p><h2 id="abreviacoes-e-conclusao" tabindex="-1">Abreviações e Conclusão <a class="header-anchor" href="#abreviacoes-e-conclusao" aria-label="Permalink to “Abreviações e Conclusão”">​</a></h2><h3 id="a-cidade-saudavel" tabindex="-1">A Cidade Saudável <a class="header-anchor" href="#a-cidade-saudavel" aria-label="Permalink to “A Cidade Saudável”">​</a></h3><p>O fortalecimento das redes de saúde e a adoção de hábitos saudáveis (exercícios, dieta, adesão terapêutica) revertem o cenário de Doenças Crônicas.</p><h3 id="principais-abreviacoes" tabindex="-1">Principais Abreviações <a class="header-anchor" href="#principais-abreviacoes" aria-label="Permalink to “Principais Abreviações”">​</a></h3><ul><li>APS: Atenção Primária à Saúde</li><li>CCNT: Condição Crônica Não Transmissível</li><li>CV: Cardiovascular</li><li>DM: Diabetes Mellitus / DMG: DM Gestacional</li><li>HA: Hipertensão Arterial</li><li>HbA1c: Hemoglobina Glicada</li><li>LOA: Lesão de Órgão-Alvo</li><li>MEV: Modificação do Estilo de Vida</li><li>TOTG: Teste de Tolerância Oral à Glicose</li><li>UBS: Unidade Básica de Saúde</li></ul>`,68)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};